import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contracts = {
  pricingPolicy:
    "artifacts/contracts/XNSPricingPolicy.sol/XNSPricingPolicy.json",
  registrar:
    "artifacts/contracts/XNSSignedQuoteRegistrar.sol/XNSSignedQuoteRegistrar.json",
};

const bundle = {};
for (const [key, relativePath] of Object.entries(contracts)) {
  const artifact = JSON.parse(
    fs.readFileSync(path.join(root, relativePath), "utf8"),
  );
  if (
    !Array.isArray(artifact.abi) ||
    typeof artifact.bytecode !== "string" ||
    !artifact.bytecode.startsWith("0x") ||
    artifact.bytecode.length <= 2
  ) {
    throw new Error("Invalid Hardhat artifact for " + key);
  }
  bundle[key] = { abi: artifact.abi, bytecode: artifact.bytecode };
}

const target = path.join(
  root,
  "frontend",
  "generated",
  "mainnetPricingDeployment.ts",
);
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(
  target,
  [
    "// Generated from Hardhat artifacts during the build.",
    "// Do not edit this file manually.",
    "export const mainnetPricingDeploymentArtifacts = " +
      JSON.stringify(bundle) +
      " as const;",
    "",
  ].join("\n"),
);
console.log("Generated", path.relative(root, target));
